#include <stdio.h>

/* teste do desafio de MODULO o-relatorio-da-portaria — counter_protocol (03-tdd 3.9.3).
   Cada cenario escreve a fila num arquivo (as idades e o 0 da sentinela),
   aponta o stdin para ele e captura o stdout no proprio teste. Os nomes dos
   temporarios sao POR CENARIO. Nunca ha fclose de stdin/stdout — so fflush. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oRelatorioDaPortaria(void);

SM_TEST(quatro_pessoas_tres_maiores) {
    /* a fila do enunciado: quatro pessoas, tres maiores, escada de tres linhas */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "20 30 15 21 0\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    oRelatorioDaPortaria();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[120] = "(nada impresso)";
    fgets(linha, 120, f);
    checa_str("a contagem de pessoas", linha, "pessoas: 4\n",
              "o laco para no 0, e o 0 nao conta como pessoa");
    fgets(linha, 120, f);
    checa_str("a soma das idades", linha, "soma: 86\n",
              "o acumulador soma cada idade lida dentro do laco");
    fgets(linha, 120, f);
    checa_str("a contagem de maiores", linha, "maiores: 3\n",
              "o contador so sobe quando a condicao da idade e verdadeira");
    fgets(linha, 120, f);
    checa_str("o titulo da escada", linha, "escada:\n",
              "a palavra sai sozinha, antes das linhas de asterisco");
    fgets(linha, 120, f);
    checa_str("a linha 1 da escada", linha, "*\n",
              "a linha 1 tem 1 asterisco(s): o laco de dentro depende do de fora");
    fgets(linha, 120, f);
    checa_str("a linha 2 da escada", linha, "**\n",
              "a linha 2 tem 2 asterisco(s): o laco de dentro depende do de fora");
    fgets(linha, 120, f);
    checa_str("a linha 3 da escada", linha, "***\n",
              "a linha 3 tem 3 asterisco(s): o laco de dentro depende do de fora");
    char fim[120] = "(nada impresso)";
    fgets(fim, 120, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "o relatorio termina na ultima linha da escada");
    fclose(f);
}

