#include <stdio.h>

void oRelatorioDaPortaria(void) {
    int pessoas = 0;
    int soma = 0;
    int maiores = 0;

    int idade = 0;
    scanf("%d", &idade);
    while (!(idade == 0)) {
        pessoas += 1;
        soma += idade;
        if (idade >= 18) {
            maiores += 1;
        }
        scanf("%d", &idade);
    }

    printf("pessoas: %d\n", pessoas);
    printf("soma: %d\n", soma);
    printf("maiores: %d\n", maiores);
    printf("escada:\n");
    for (int i = 1; i <= maiores; i++) {
        for (int j = 1; j <= i; j++) {
            printf("*");
        }
        printf("\n");
    }
}
